/**
 * The "רישיונות" screen's data (spec §23 "רישיונות"; work plan stage 14): generated by scripts/licenses.mjs
 * (`npm run licenses`) into third-party-licenses.json, never edited by hand:
 * - the fonts the app embeds (Rubik, Teko: SIL Open Font License 1.1) with their copyright lines, and the OFL
 *   text itself, verbatim from @expo-google-fonts' LICENSE_FONT;
 * - every package of apps/mobile's production dependency closure: name, version, license (an SPDX id or
 *   expression) and the copyright lines of its license file;
 * - the full text of each common license (MIT, ISC, BSD, Apache-2.0…), from an installed package's own file.
 * License texts stay in English: they are legal texts, shown as they are, left to right.
 */

export interface FontNotice {
  family: string;
  copyright: string[];
  license: string;
}

/** [name, version, license, copyright lines]: compact, the file lists hundreds. */
export type PackageTuple = [string, string, string, string[]];

export interface LicensesData {
  fonts: FontNotice[];
  ofl: string;
  texts: Record<string, string>;
  packages: PackageTuple[];
}

export interface PackageRow {
  key: string;
  name: string;
  version: string;
  license: string;
  copyright: string[];
}

let loaded: LicensesData | null = null;

/** The file (about 80 KB of JSON), read when the screen first opens: not at the app's start (docs/PERF.md). */
export function licensesData(): LicensesData {
  loaded ??= require('./third-party-licenses.json') as LicensesData;
  return loaded;
}

export function packageRows(data: LicensesData): PackageRow[] {
  return data.packages.map(([name, version, license, copyright]) => ({
    key: `${name}@${version}`,
    name,
    version,
    license,
    copyright,
  }));
}

/** The license texts the file has, most used first (then by name). */
export function licenseTexts(data: LicensesData): { id: string; text: string; packages: number }[] {
  const uses = new Map<string, number>();
  for (const [, , license] of data.packages) {
    for (const id of Object.keys(data.texts)) if (license.includes(id)) uses.set(id, (uses.get(id) ?? 0) + 1);
  }
  return Object.entries(data.texts)
    .map(([id, text]) => ({ id, text, packages: uses.get(id) ?? 0 }))
    .sort((a, b) => b.packages - a.packages || (a.id < b.id ? -1 : 1));
}
